insert into public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) values
('Федеральное Собрание · конституционные процедуры','Совет Федерации решил возложить принятие своего регламента на Государственную Думу. Какой принцип нарушен?','["Регламенты обеих палат принимает Президент","Обе палаты обязаны принимать единый регламент совместным голосованием","Каждая палата принимает собственный регламент","Регламент утверждает Правительство по представлению палат"]'::jsonb,2,'Конституция Российской Федерации','статья 101','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 101 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Совет Федерации намерен передать Государственной Думе назначение выборов Президента РФ. Какой вывод следует из Конституции?','["Это полномочие Государственной Думы по вопросу доверия","Назначение выборов Президента — собственное полномочие Совета Федерации","Оно совместно исполняется двумя палатами одним постановлением","Назначение проводится постановлением Правительства"]'::jsonb,1,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 102 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Предложено, чтобы решение о возможности использования Вооружённых Сил РФ за рубежом приняла только Государственная Дума. Соответствует ли это Конституции?','["Нет, решение относится к ведению Совета Федерации","Да, Дума решает этот вопрос как нижняя палата","Да, если присутствует большинство фракций","Да, в форме федерального закона, который не рассматривается Советом Федерации"]'::jsonb,0,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 102 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Какой орган утверждает представленные Президентом кандидатуры заместителей Председателя Правительства, кроме предусмотренных исключений?','["Совет Федерации","Счётная палата","Верховный Суд","Государственная Дума"]'::jsonb,3,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 103 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Федеральное министерство предложило Государственной Думе объявить амнистию распоряжением Правительства. Какая форма компетенции предусмотрена Конституцией?','["Амнистия оформляется только указом губернатора","Амнистию объявляет Совет Федерации совместно с Президентом","Амнистия объявляется Государственной Думой","Амнистия требует решения Конституционного Суда"]'::jsonb,2,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 103 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Законодательное собрание региона подготовило федеральный законопроект. Куда реализуется его право законодательной инициативы?','["Непосредственно в Совет Федерации для принятия","В Государственную Думу","В Правительство для обязательного утверждения","В Конституционный Суд для законодательного голосования"]'::jsonb,1,'Конституция Российской Федерации','статья 104','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 104 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Палата предлагает считать обычный федеральный закон принятым Государственной Думой большинством только участвовавших депутатов. Какой стандарт установлен Конституцией?','["Большинство от общего числа депутатов Государственной Думы","Большинство от числа присутствовавших депутатов","Большинство голосов фракций, независимо от числа депутатов","Большинство от общего числа сенаторов"]'::jsonb,0,'Конституция Российской Федерации','статья 105','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 105 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Принятый Государственной Думой федеральный закон не был рассмотрен Советом Федерации четырнадцать дней. Каково общее правило статьи 105, если обязательное рассмотрение не требуется?','["Закон считается отклонённым без дополнительного голосования","Государственная Дума автоматически обязана его принять повторно","Правительство вправе само подписать закон","Закон считается одобренным Советом Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 105','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 105 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Совет Федерации намерен не рассматривать принятый Думой федеральный закон по вопросам войны и мира. Как это оценивает Конституция?','["Рассмотрение факультативно для всех видов законов","Вопросы войны и мира входят только в бюджетный комитет Госдумы","Такой закон подлежит обязательному рассмотрению Советом Федерации","Закон должен рассматриваться лишь Конституционным Судом"]'::jsonb,2,'Конституция Российской Федерации','статья 106','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 106 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','К какой категории законов применяется обязательное рассмотрение Советом Федерации по статье 106?','["К любому региональному закону об областном бюджете","К федеральным законам по вопросам федерального бюджета","К решениям муниципальных представительных органов","К внутренним постановлениям фракций Госдумы"]'::jsonb,1,'Конституция Российской Федерации','статья 106','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 106 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Для преодоления президентского отклонения обычного федерального закона в обеих палатах какой порог применяется?','["Не менее двух третей голосов от общего числа в каждой палате","Простое большинство присутствующих в каждой палате","Три четверти сенаторов и простое большинство депутатов","Две трети депутатов и простое большинство сенаторов"]'::jsonb,0,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 107 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Чем отличается принятие федерального конституционного закона от обычного федерального закона?','["Достаточно большинства от присутствующих сенаторов и депутатов","Не требуется одобрения Совета Федерации","Для обоих применяется только простое большинство депутатов","Необходимы не менее трёх четвертей сенаторов и двух третей депутатов"]'::jsonb,3,'Конституция Российской Федерации','статья 108','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 108 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Президент рассматривает роспуск Государственной Думы в период действия чрезвычайного положения на всей территории России. Какое правило действует?','["Роспуск обязателен после выражения недоверия","Роспуск разрешён по решению Председателя Правительства","Роспуск в этот период запрещён","Ограничение касается только региональных парламентов"]'::jsonb,2,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 109 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Кто осуществляет исполнительную власть Российской Федерации в соответствии с действующей редакцией статьи 110?','["Президент единолично вместо Правительства","Правительство Российской Федерации под общим руководством Президента РФ","Совет Федерации вместе с Государственной Думой","Федеральное Собрание в лице двух палат"]'::jsonb,1,'Конституция Российской Федерации','статья 110','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 110 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true),
('Федеральное Собрание · конституционные процедуры','Правительство предлагает переложить внесение проекта федерального бюджета на Совет Федерации. Как распределено полномочие статьёй 114?','["Правительство разрабатывает и представляет бюджет Государственной Думе","Совет Федерации самостоятельно вносит бюджет","Бюджет представляется Конституционному Суду","Президент передаёт проект бюджета непосредственно региональным парламентам"]'::jsonb,0,'Конституция Российской Федерации','статья 114','https://www.consultant.ru/document/cons_doc_LAW_28399/','Основание — статья 114 Конституции РФ; компетенция и процедура определяются непосредственно конституционной нормой.',true)
